import{_ as e,o,c as r,a4 as a}from"./chunks/framework.bruR1JhL.js";const p=JSON.parse('{"title":"Convert to PDF","description":"Turn Word, PowerPoint and Excel files, images, web pages, HTML and Markdown into PDF files.","frontmatter":{"title":"Convert to PDF","description":"Turn Word, PowerPoint and Excel files, images, web pages, HTML and Markdown into PDF files."},"headers":[],"relativePath":"docs/to-pdf.md","filePath":"docs/to-pdf.md","lastUpdated":1795509372000}'),s={name:"docs/to-pdf.md"};function n(i,t,d,l,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="convert-to-pdf" tabindex="-1">Convert to PDF <a class="header-anchor" href="#convert-to-pdf" aria-label="Permalink to &quot;Convert to PDF&quot;">​</a></h1><p>These tools turn other kinds of files into PDFs: Office documents, images, web pages and HTML, and Markdown. You can add a file with the tool&#39;s own buttons, drag it in from the Explorer, right-click it in the Explorer and choose <strong>Convert to PDF</strong>, or select it and use the <strong>Convert to PDF</strong> button in the Preview panel. Each of these opens the right tool for the file type. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the controls all tools share.</p><p>Tilepress never overwrites a file without asking. When a tool saves next to the original or in a folder you chose, and a file with that name already exists, it adds a number, for example <code>report (2).pdf</code>. When a tool shows a Save dialog, Windows asks before replacing a file. Every conversion is listed in <a href="/tilepress/docs/history">History</a>.</p><h2 id="word-to-pdf" tabindex="-1">Word to PDF <a class="header-anchor" href="#word-to-pdf" aria-label="Permalink to &quot;Word to PDF&quot;">​</a></h2><p>Converts Word documents to PDF using Microsoft Word or LibreOffice. Use it for one document or a whole batch.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Click <strong>Add word documents…</strong> and pick one or more files. You can also drag files from the Explorer onto the list, or select a document in the Explorer and click <strong>Add</strong> followed by its name.</li><li>Check the line under the title. It says which app will do the conversion, for example <strong>Converts with Microsoft Word</strong>.</li><li>Set the options in the <strong>Options</strong> card.</li><li>Choose where to save: <strong>Save next to each document</strong>, or <strong>Save in a folder</strong> and then <strong>Choose…</strong>.</li><li>Click <strong>Convert to PDF</strong> (with several files, the button says <strong>Convert 3 to PDF</strong>, and so on).</li></ol><p>Each row shows <strong>Ready</strong>, then <strong>Converting…</strong>, then the new file&#39;s name, page count and size, with <strong>Open</strong> and <strong>Show in folder</strong> buttons. If a file fails, its row shows the reason and the others carry on.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Create bookmarks from headings</td><td>Adds a PDF bookmark for each heading in the document.</td><td>On</td></tr><tr><td>Include comments and tracked changes</td><td>Shows comments and tracked changes in the PDF, as Word displays them.</td><td>Off</td></tr><tr><td>Optimise for</td><td><strong>Printing (best quality)</strong> or <strong>Screen (smaller file)</strong>.</td><td>Printing (best quality)</td></tr><tr><td>PDF/A (for long-term archiving)</td><td>Makes a PDF/A file, a PDF format meant for archives.</td><td>Off</td></tr><tr><td>Where to save</td><td><strong>Save next to each document</strong> or <strong>Save in a folder</strong>.</td><td>Save next to each document</td></tr></tbody></table><p>When both Microsoft Word and LibreOffice are installed, the engine line becomes a list where you can choose <strong>Microsoft Word (best)</strong> or <strong>LibreOffice</strong>.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Accepts DOC, DOCX, DOCM, DOT, DOTX, DOTM, RTF and ODT files.</li><li>The PDF has the same name as the document, with <code>.pdf</code> at the end.</li><li>The options in the table apply to Microsoft Word only. With LibreOffice, the tool says so and LibreOffice uses its own settings.</li><li>See <a href="#office-conversions">Office conversions</a> below for how Word and LibreOffice are found and run.</li></ul><h2 id="powerpoint-to-pdf" tabindex="-1">PowerPoint to PDF <a class="header-anchor" href="#powerpoint-to-pdf" aria-label="Permalink to &quot;PowerPoint to PDF&quot;">​</a></h2><p>Converts presentations to PDF using Microsoft PowerPoint or LibreOffice. You can export the slides, the notes pages or handouts.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Click <strong>Add powerpoint presentations…</strong>, drag presentations from the Explorer onto the list, or select one in the Explorer and click <strong>Add</strong> followed by its name.</li><li>Check which app the line under the title names (<strong>Converts with Microsoft PowerPoint</strong> or <strong>Converts with LibreOffice</strong>).</li><li>Pick a <strong>Layout</strong> and the other options in the <strong>Options</strong> card.</li><li>Choose <strong>Save next to each presentation</strong> or <strong>Save in a folder</strong>.</li><li>Click <strong>Convert to PDF</strong>.</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Layout</td><td><strong>Slides</strong>, <strong>Notes pages</strong>, or <strong>Handouts, 2 per page</strong>, <strong>Handouts, 3 per page</strong> or <strong>Handouts, 6 per page</strong>.</td><td>Slides</td></tr><tr><td>Include hidden slides</td><td>Also exports slides that are hidden in the presentation.</td><td>Off</td></tr><tr><td>Frame slides</td><td>Draws a thin frame around each slide.</td><td>Off</td></tr><tr><td>Optimise for</td><td><strong>Printing (best quality)</strong> or <strong>Screen (smaller file)</strong>.</td><td>Printing (best quality)</td></tr><tr><td>PDF/A (for long-term archiving)</td><td>Makes a PDF/A file.</td><td>Off</td></tr><tr><td>Where to save</td><td><strong>Save next to each presentation</strong> or <strong>Save in a folder</strong>.</td><td>Save next to each presentation</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Accepts PPT, PPTX, PPTM, PPS, PPSX, POT, POTX and ODP files.</li><li>The PDF has the same name as the presentation, with <code>.pdf</code> at the end.</li><li>Layout and the other options apply to Microsoft PowerPoint only. LibreOffice exports the slides with its own settings.</li></ul><h2 id="excel-to-pdf" tabindex="-1">Excel to PDF <a class="header-anchor" href="#excel-to-pdf" aria-label="Permalink to &quot;Excel to PDF&quot;">​</a></h2><p>Converts spreadsheets to PDF using Microsoft Excel or LibreOffice. You can export the whole workbook or only the active sheet.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Click <strong>Add excel spreadsheets…</strong>, drag spreadsheets from the Explorer onto the list, or select one in the Explorer and click <strong>Add</strong> followed by its name.</li><li>Check which app the line under the title names.</li><li>Set <strong>Sheets</strong> and the other options in the <strong>Options</strong> card.</li><li>Choose <strong>Save next to each spreadsheet</strong> or <strong>Save in a folder</strong>.</li><li>Click <strong>Convert to PDF</strong>.</li></ol><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Sheets</td><td><strong>Whole workbook</strong>, or <strong>Active sheet only</strong> (the sheet that was open when the file was last saved).</td><td>Whole workbook</td></tr><tr><td>Fit each sheet to one page wide</td><td>Scales each sheet so its columns fit across one page. Long sheets still run over several pages.</td><td>On</td></tr><tr><td>Landscape pages</td><td>Turns every sheet&#39;s pages to landscape.</td><td>Off</td></tr><tr><td>Use print areas set in the workbook</td><td>Exports only the print areas the workbook defines. Untick it to export everything.</td><td>On</td></tr><tr><td>Optimise for</td><td><strong>Printing (best quality)</strong> or <strong>Screen (smaller file)</strong>.</td><td>Printing (best quality)</td></tr><tr><td>PDF/A (for long-term archiving)</td><td>Makes a PDF/A file.</td><td>Off</td></tr><tr><td>Where to save</td><td><strong>Save next to each spreadsheet</strong> or <strong>Save in a folder</strong>.</td><td>Save next to each spreadsheet</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Accepts XLS, XLSX, XLSM, XLSB, XLTX, XLTM, ODS and CSV files.</li><li>The PDF has the same name as the spreadsheet, with <code>.pdf</code> at the end.</li><li>The page setup changes (fit to width, landscape) are made to a read-only copy that Excel has open. Your spreadsheet isn&#39;t changed.</li><li>Links to other workbooks aren&#39;t updated during the conversion.</li><li>The options apply to Microsoft Excel only. LibreOffice uses its own settings.</li></ul><h3 id="office-conversions" tabindex="-1">Office conversions <a class="header-anchor" href="#office-conversions" aria-label="Permalink to &quot;Office conversions&quot;">​</a></h3><p>These points apply to Word to PDF, PowerPoint to PDF and Excel to PDF.</p><ul><li><strong>You need Microsoft Office or LibreOffice.</strong> Tilepress checks for each Office app separately (Word, Excel, PowerPoint), so you can have one and not the others. It finds LibreOffice on your <code>PATH</code> or in <code>Program Files\\LibreOffice</code>.</li><li><strong>Which one is used.</strong> Microsoft Office is used when it&#39;s installed, because its output is closest to the original. Otherwise LibreOffice is used. If both are installed, you can switch in the list under the title.</li><li><strong>If neither is installed</strong>, the tool shows a message and the convert button stays disabled. After installing one, click <strong>Check again</strong> in that message; you don&#39;t need to restart Tilepress.</li><li><strong>Your documents are safe.</strong> Files are opened read-only, and macros are turned off before a file is opened. Office runs invisibly as its own copy, so documents you have open aren&#39;t touched, and Tilepress only closes the copy it started. LibreOffice runs with a separate, temporary profile, so it works even while you have LibreOffice open.</li><li><strong>One at a time.</strong> Files convert one after another. If you click the button again, files that already converted are skipped, and files that failed are tried again.</li><li><strong>Password-protected</strong> Word and Excel files fail with an error instead of asking for the password.</li><li><strong>Time limit.</strong> LibreOffice gets 5 minutes per file and is stopped after that.</li></ul><h2 id="jpg-to-pdf" tabindex="-1">JPG to PDF <a class="header-anchor" href="#jpg-to-pdf" aria-label="Permalink to &quot;JPG to PDF&quot;">​</a></h2><p>Turns images into PDF pages: one PDF with all the images in order, or one PDF per image. JPEG photos keep their exact quality, and other formats are stored without loss.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Click <strong>Add images…</strong>, drag images from the Explorer onto the list, or select one in the Explorer and click <strong>Add</strong> followed by its name.</li><li>Put the images in order. Drag rows up or down, use the <strong>Move up</strong> and <strong>Move down</strong> buttons, or click <strong>Sort A–Z</strong> to sort by file name.</li><li>Turn any image that&#39;s on its side with <strong>Rotate left</strong> or <strong>Rotate right</strong>. Remove one with the <strong>×</strong> button.</li><li>Set up the pages in the <strong>Page setup</strong> card. The small page next to each image shows how it will sit on its page.</li><li>Choose <strong>One PDF with all images</strong> or <strong>One PDF per image</strong>.</li><li>Click <strong>Convert and save…</strong> and choose a name and folder. With <strong>One PDF per image</strong>, the button says <strong>Convert each to PDF</strong> and saves without asking, next to each image or in the folder you chose.</li></ol><p>When it&#39;s done, a <strong>Saved</strong> card appears with <strong>Open</strong> and <strong>Show in folder</strong>. For a single PDF, <strong>Keep editing this file</strong> opens it in the page tools (see <a href="/tilepress/docs/pdf-pages">Combine, split &amp; pages</a>).</p><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Page size</td><td><strong>Same as image</strong>, <strong>A4</strong>, <strong>Letter</strong>, <strong>Legal</strong>, <strong>A3</strong> or <strong>A5</strong>. <strong>Same as image</strong> makes each page exactly the size of its image (plus the margin).</td><td>A4</td></tr><tr><td>Orientation</td><td><strong>Match each image</strong> (landscape pages for wide images, portrait for tall ones), <strong>Portrait</strong> or <strong>Landscape</strong>. Not available with <strong>Same as image</strong>.</td><td>Match each image</td></tr><tr><td>Margin</td><td><strong>None</strong>, <strong>Small (10 mm)</strong> or <strong>Large (20 mm)</strong>.</td><td>Small (10 mm)</td></tr><tr><td>Image</td><td><strong>Fit whole image</strong> shows all of it; <strong>Fill page (crop edges)</strong> fills the area inside the margin and cuts off what doesn&#39;t fit. Not available with <strong>Same as image</strong>.</td><td>Fit whole image</td></tr><tr><td>Output</td><td><strong>One PDF with all images</strong> or <strong>One PDF per image</strong>.</td><td>One PDF with all images</td></tr><tr><td>Where to save (one PDF per image)</td><td><strong>Save next to each image</strong> or <strong>Save in a folder</strong>.</td><td>Save next to each image</td></tr></tbody></table><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Accepts JPG, JPEG, JFIF, PNG, GIF, BMP, TIF, TIFF and WebP. To use a HEIC, AVIF or ICO picture, convert it to JPG first with <a href="/tilepress/docs/img-optimize">Convert to JPG</a>.</li><li>A multi-page TIFF becomes one page per frame. An animated GIF uses its first frame only.</li><li>JPEG photos are normally copied into the PDF byte for byte, so there&#39;s no quality loss. PNG, GIF, BMP, TIFF and WebP are stored losslessly, and transparency is kept.</li><li>Photos are placed upright, following the camera&#39;s rotation setting.</li><li>With <strong>Same as image</strong>, the page size comes from the image&#39;s resolution (dpi) when the file records one, otherwise 96 dpi.</li><li>The bar at the bottom counts the images and the pages they will make.</li><li>For one PDF, the suggested name is the image&#39;s name with <code>.pdf</code>, or <code>images.pdf</code> in the first image&#39;s folder when there are several. For one PDF per image, each PDF has the image&#39;s name with <code>.pdf</code>.</li></ul><h2 id="html-to-pdf" tabindex="-1">HTML to PDF <a class="header-anchor" href="#html-to-pdf" aria-label="Permalink to &quot;HTML to PDF&quot;">​</a></h2><p>Prints a web page, an HTML file or HTML code that you paste or type to a PDF. It uses WebView2, the Chromium engine that also draws the Tilepress window.</p><h3 id="how-to-use-it-4" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-4" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Choose the source at the top: <strong>Web page</strong>, <strong>HTML file</strong> or <strong>HTML code</strong>.</li><li>Give it the content: <ul><li><strong>Web page:</strong> type or paste the address, for example <code>example.com/article</code>.</li><li><strong>HTML file:</strong> click <strong>Choose file…</strong>, drag an <code>.html</code> file from the Explorer, or click <strong>Use</strong> followed by the name of the file selected in the Explorer.</li><li><strong>HTML code:</strong> type or paste HTML in the box. A preview appears beside it.</li></ul></li><li>Set up the pages in the <strong>Page setup</strong> card.</li><li>Click <strong>Convert and save…</strong> and choose a name and folder. For a web page you can also press <kbd>Enter</kbd> in the address box.</li></ol><p>When it&#39;s done, a <strong>Saved</strong> card appears with <strong>Open</strong>, <strong>Show in folder</strong> and <strong>Keep editing this file</strong>, which opens the PDF in the page tools.</p><h3 id="options-4" tabindex="-1">Options <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Page size</td><td><strong>A4</strong>, <strong>Letter</strong>, <strong>Legal</strong>, <strong>A3</strong> or <strong>A5</strong>.</td><td>A4</td></tr><tr><td>Orientation</td><td><strong>Portrait</strong> or <strong>Landscape</strong>.</td><td>Portrait</td></tr><tr><td>Margins</td><td><strong>None</strong>, <strong>Narrow (6 mm)</strong>, <strong>Normal (12 mm)</strong> or <strong>Wide (25 mm)</strong>.</td><td>Normal (12 mm)</td></tr><tr><td>Scale (%)</td><td>Makes the content smaller or larger on the page, from 10 to 200.</td><td>100</td></tr><tr><td>Wait after loading (s)</td><td>Extra seconds to wait after the page has loaded, from 0 to 30. Web page only.</td><td>0</td></tr><tr><td>Print background colours and images</td><td>Keeps the page&#39;s background colours and images.</td><td>On</td></tr><tr><td>Header and footer (title, date, page numbers)</td><td>Adds a header and footer to each page.</td><td>Off</td></tr><tr><td>Scroll through the page first, so lazy-loaded images appear</td><td>Scrolls down the whole page before printing, so images that load only when you scroll are included. Web page only.</td><td>On</td></tr></tbody></table><h3 id="good-to-know-4" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-4" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Web addresses:</strong> if you leave out <code>https://</code>, it&#39;s added. Only <code>http://</code> and <code>https://</code> addresses work.</li><li><strong>Logins:</strong> the page loads in a hidden window, so a site that needs you to sign in prints as it looks to a signed-out visitor.</li><li><strong>Waiting for the page:</strong> Tilepress waits up to 60 seconds for the page to load, then up to 15 more seconds for its fonts and images. If the page can&#39;t load, you see &quot;The page couldn&#39;t be loaded. Check the address and your internet connection.&quot;</li><li><strong>Files:</strong> accepts <code>.html</code>, <code>.htm</code> and <code>.xhtml</code> files.</li><li><strong>Pasted code:</strong> you can paste a whole document or just a fragment; a fragment is wrapped in a page for you. Styles in <code>&lt;style&gt;</code> tags are kept. The preview beside the box doesn&#39;t run scripts, but the PDF is made from the full page. Links to local files by relative path don&#39;t work for pasted code, because it&#39;s printed from a temporary copy.</li><li><strong>Header and footer:</strong> for a web page or an HTML file, the footer shows the page&#39;s address. For pasted code, the header shows the PDF&#39;s file name instead of a temporary path.</li><li><strong>Suggested name:</strong> for a web page, the site and page name in your Downloads folder (for example <code>example.com-article.pdf</code>). For an HTML file, the file&#39;s name with <code>.pdf</code>, next to it. For pasted code, <code>page.pdf</code> in Downloads.</li><li><strong>Your files:</strong> the page being printed can&#39;t read other files on your PC through scripts.</li><li><strong>Network use:</strong> printing a web page downloads it, like opening it in a browser. HTML files and pasted code can also load pictures, fonts or scripts from the internet if they link to them. See <a href="/tilepress/docs/privacy">Privacy</a>.</li></ul><h2 id="markdown-to-pdf" tabindex="-1">Markdown to PDF <a class="header-anchor" href="#markdown-to-pdf" aria-label="Permalink to &quot;Markdown to PDF&quot;">​</a></h2><p>Turns a <code>.md</code> file, or Markdown you type, into a formatted PDF with tables, highlighted code and pictures. A live preview shows the result as you type.</p><h3 id="how-to-use-it-5" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-5" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Click <strong>Open .md file…</strong>, drag a <code>.md</code> file from the Explorer onto the editor, or click <strong>Use</strong> followed by the name of the Markdown file selected in the Explorer. You can also type in the editor straight away; it starts with a short example you can replace.</li><li>Edit the text if you like. The preview on the right updates a moment after you stop typing.</li><li>Pick a <strong>Theme</strong>.</li><li>Set up the pages in the <strong>Page setup</strong> card.</li><li>Click <strong>Convert and save…</strong> and choose a name and folder.</li></ol><p>To start over with an empty editor after opening a file, click <strong>New text</strong>.</p><h3 id="options-5" tabindex="-1">Options <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Theme</td><td><strong>GitHub</strong> (clean sans-serif), <strong>Document (serif)</strong> (justified text, centred title) or <strong>Compact</strong> (smaller text and spacing).</td><td>GitHub</td></tr><tr><td>Page size</td><td><strong>A4</strong>, <strong>Letter</strong>, <strong>Legal</strong>, <strong>A3</strong> or <strong>A5</strong>.</td><td>A4</td></tr><tr><td>Orientation</td><td><strong>Portrait</strong> or <strong>Landscape</strong>.</td><td>Portrait</td></tr><tr><td>Margins</td><td><strong>None</strong>, <strong>Narrow (6 mm)</strong>, <strong>Normal (12 mm)</strong> or <strong>Wide (25 mm)</strong>.</td><td>Wide (25 mm)</td></tr><tr><td>Scale (%)</td><td>Makes the content smaller or larger, from 10 to 200.</td><td>100</td></tr><tr><td>Print background colours and images</td><td>Keeps background colours, such as code block shading and table stripes.</td><td>On</td></tr><tr><td>Header and footer (title, date, page numbers)</td><td>Adds a header and footer to each page. The header shows the document&#39;s title.</td><td>Off</td></tr></tbody></table><h3 id="good-to-know-5" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-5" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Accepts <code>.md</code> and <code>.markdown</code> files.</li><li>Editing the text changes only the PDF. Your <code>.md</code> file isn&#39;t modified.</li><li>Supported Markdown: standard CommonMark, plus tables and <s>strikethrough</s>. Quotes and dashes are made typographic. HTML inside the Markdown is allowed.</li><li>Code blocks are highlighted when you name the language after the opening fence, for example <code>```python</code>.</li><li><strong>Pictures:</strong> local images written as <code>![alt](picture.png)</code> are found relative to the <code>.md</code> file&#39;s folder (or by full path) and built into the PDF. Each can be up to 15 MB. When you type Markdown without opening a file, use full paths for local images. Images given as web addresses are downloaded from the internet, both for the preview and for the PDF.</li><li><strong>Title:</strong> the file&#39;s name, or for typed text the first <code># Heading</code>. It&#39;s used in the header (when turned on) and for the suggested file name.</li><li><strong>Suggested name:</strong> next to the <code>.md</code> file with <code>.pdf</code>, or for typed text, the title with <code>.pdf</code> in your Downloads folder.</li></ul>',59)])])}const f=e(s,[["render",n]]);export{p as __pageData,f as default};
